"""
Printed half-wave dipole for LoRa 868 MHz - reference antenna (2.15 dBi) for comparing the Moxon.

Single-sided board (home etching or JLCPCB), the only part is the coax feed:

  * AE1 is the dipole copper itself, one footprint generated by layout.py from dipole-868-dims.json
    (written by sim.py): pad 1 / pad 2 are the two halves. Feed impedance about 70 Ohm, SWR ~1.4 at
    50 Ohm (0.2 dB mismatch loss), no matching network.
  * J1 are the solder pads for a 50 Ohm pigtail (RG316 / RG174, other end SMA) on the feed gap:
    centre conductor to pad 1, shield to pad 2. The cable leaves at right angles to the dipole.

Run with:  python board.py   (writes the netlist; schematic.py draws the schematic)
"""

from pathlib import Path

from skidl import *

HERE = Path(__file__).resolve().parent
PROJECT = "dipole-868"
set_default_tool(KICAD9)
footprint_search_paths[KICAD9].append(str(HERE))

# Parts ---------------------------------------------------------------------------------------
ant = Part("Device", "Antenna_Dipole", ref="AE1", value="Dipole 868MHz", footprint=f"{PROJECT}:Dipole_868")
feed = Part("Connector", "Conn_Coaxial", ref="J1", value="RG316 pigtail", footprint=f"{PROJECT}:CoaxFeed_Gap2mm")

# Nets ----------------------------------------------------------------------------------------
Net("RF").connect(feed["In"], ant[1])
Net("RF_SHIELD").connect(feed["Ext"], ant[2])

# Output --------------------------------------------------------------------------------------
if __name__ == "__main__":
    ERC()
    generate_netlist(file_=str(HERE / f"{PROJECT}.net"))
